```python
import json
from collections import Counter

def count_data_sources(file_path):
    counter = Counter()
    with open(file_path, 'r', encoding='utf-8') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            try:
                obj = json.loads(line)
                if 'data_source' in obj:
                    counter[obj['data_source']] += 1
            except json.JSONDecodeError:
                # 忽略坏 JSON 行
                continue
    return counter

# 使用示例
if __name__ == '__main__':
    counts = count_data_sources('data.jsonl')
    for source, count in counts.items():
        print(f'{source}: {count}')
```
这段代码会忽略空行和解析失败的行，只统计包含 `data_source` 字段的对象。

